const textSources=new WeakMap(),attributeSources=new WeakMap();
function translateText(text){if(portalLanguage==='vi')return text;const m=text.match(/^(\s*)([\s\S]*?)(\s*)$/),base=m[2];let value=english[base];if(value===undefined){value=base.replace(/^Đã lưu: ([\d.]+) giây$/,'Saved: $1 seconds').replace(/^Tự tắt sau ([\d.]+) giây$/,'Turns off in $1 seconds').replace(/^Cập nhật /,'Updated ').replace(/^Đến /,'Until ').replace(/^(\d+) ngày (\d+) giờ$/,(all,d,h)=>d+' '+(+d===1?'day':'days')+' '+h+' '+(+h===1?'hour':'hours')).replace(/^(\d+) giờ (\d+) phút$/,(all,h,m)=>h+' '+(+h===1?'hour':'hours')+' '+m+' '+(+m===1?'minute':'minutes')).replace(/^(FakeLag|Ghost|Telekill) · Tắt$/,'$1 · Off').replace(/^(FakeLag|Ghost|Telekill) · Bật$/,'$1 · On').replace(/^Cập nhật (.+)\. Đây là trạng thái nút, không phải xác nhận VPN\.$/,'Updated $1. This is the control state, not VPN confirmation.').replace(/^Liên kết cấu hình: /,'Configuration link: ');}return m[1]+value+m[3];}
function translatePortal(){document.documentElement.lang=portalLanguage;document.title=portalLanguage==='vi'?'Mizze · Kết nối':'Mizze · Connection';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(['SCRIPT','STYLE','CODE','OPTION'].includes(node.parentElement?.tagName))continue;let entry=textSources.get(node);if(!entry||node.nodeValue!==entry.last)entry={base:node.nodeValue,last:node.nodeValue};let translated=translateText(entry.base);if(node.nodeValue!==translated)node.nodeValue=translated;entry.last=translated;textSources.set(node,entry);}for(const el of document.querySelectorAll('[aria-label],[placeholder],[alt]')){let entries=attributeSources.get(el)||{};for(const key of ['aria-label','placeholder','alt'])if(el.hasAttribute(key)){let current=el.getAttribute(key),entry=entries[key];if(!entry||entry.last!==current)entry={base:current,last:current};let translated=translateText(entry.base);if(current!==translated)el.setAttribute(key,translated);entry.last=translated;entries[key]=entry;}attributeSources.set(el,entries);}for(const el of document.querySelectorAll('[data-language]'))el.value=portalLanguage;}
for(const el of document.querySelectorAll('[data-language]'))el.addEventListener('change',()=>{portalLanguage=el.value==='en'?'en':'vi';localStorage.setItem('mizze-language',portalLanguage);translatePortal();});
let languageTick=false;new MutationObserver(()=>{if(languageTick)return;languageTick=true;queueMicrotask(()=>{languageTick=false;translatePortal();});}).observe(document.body,{subtree:true,childList:true,characterData:true});translatePortal();

const $=id=>document.getElementById(id),modes=['fakelag','ghost','telekill'];let grant=null,connection=null,busy=false,enteredKey='',license=null,signalTimer=null,expiryTimer=null,currentTab='connect';
let device=localStorage.getItem('mizze-device');if(!/^[a-f0-9]{32}$/.test(device||'')){device=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');localStorage.setItem('mizze-device',device);}
function message(s,type=''){s=String(s).replace(/Add Happ/g,'Thêm vào Happ').replace(/Gateway/g,'Máy chủ').replace(/gateway/g,'máy chủ');if(/Failed to fetch|NetworkError|aborted/i.test(s))s='Không kết nối được máy chủ.';const el=$('dashboard').hidden?$('message'):$('connection-message');el.textContent=s;el.className='portal-message '+type;}
async function api(url,data,token){let c=new AbortController(),timer=setTimeout(()=>c.abort(),20000);try{let r=await fetch(url,{method:data?'POST':'GET',headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:c.signal});let b=await r.json();if(!r.ok)throw Error(b.error||'Không kết nối được máy chủ.');return b;}finally{clearTimeout(timer)}}
function selectTab(tab){currentTab=tab;$('page-title').textContent={connect:'Kết nối',shortcuts:'Phím tắt',guide:'Hướng dẫn'}[tab];$('key-label').hidden=tab!=='connect';for(let t of ['connect','shortcuts','guide'])$('panel-'+t).hidden=t!==tab;for(let b of document.querySelectorAll('[data-tab]')){if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}window.scrollTo({top:0,behavior:'instant'});}
function renderExpiry(){const end=connection?.expiresAt||license?.expiresAt;if(end){let left=Math.max(0,end-Date.now()),hours=Math.floor(left/3600000),mins=Math.floor(left/60000)%60;$('expiry').textContent=hours>=24?Math.floor(hours/24)+' ngày '+hours%24+' giờ':hours+' giờ '+mins+' phút';$('expiry-detail').textContent='Đến '+new Date(end).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'});$('key-status').textContent=left>0?'Key còn hạn':'Key đã hết hạn';}else{$('key-status').textContent='Key hợp lệ';$('expiry').textContent='Chưa bắt đầu';$('expiry-detail').textContent='Từ khi thêm vào Happ';}}
function resetConnectionUi(){clearTimeout(countdownTimer);savedTiming=null;currentControl={};for(const m of modes){$('seconds-'+m).value='0';$('seconds-'+m).dataset.dirty='';$('timer-state-'+m).textContent='Chưa tải cấu hình';} $('shortcuts').hidden=true;$('shortcut-pending').hidden=false;$('fallback').hidden=true;$('copy').hidden=true;$('binding').textContent='Chưa liên kết';$('add').innerHTML='Thêm vào Happ <span aria-hidden="true">↗</span>';$('signal').textContent='Chưa có trạng thái';$('signal-time').textContent='';$('shortcut-copy-status').textContent='';$('signal-dot').classList.remove('live');for(let [m,label]of [['fakelag','FakeLag'],['ghost','Ghost'],['telekill','Telekill']]){$('link-'+m).value='';$('mode-'+m).textContent=label+' · Tắt';$('mode-'+m).classList.remove('on');$('shortcut-'+m).textContent='Tắt';$('shortcut-'+m).classList.remove('on');}}
function showDashboard(){ $('login-screen').hidden=true;$('dashboard').hidden=false;$('key-label').textContent='Key '+enteredKey.slice(0,Math.min(7,enteredKey.length))+'••••'+enteredKey.slice(-4);$('add').disabled=false;renderExpiry();clearInterval(expiryTimer);expiryTimer=setInterval(renderExpiry,30000);selectTab('connect');}
function buildShortcuts(key,subscription){if(!/^[a-zA-Z0-9_-]{6,180}$/.test(key))throw Error('Key không hợp lệ.');const base=new URL(subscription).origin;return Object.fromEntries(modes.map(mode=>[mode,base+'/'+encodeURIComponent(key)+'/'+mode]));}
function renderConnection(){connection.shortcuts=buildShortcuts(enteredKey,connection.subscription);$('fallback').href=connection.addUrl;$('fallback').hidden=true;$('copy').hidden=false;$('shortcuts').hidden=false;$('shortcut-pending').hidden=true;$('binding').textContent='Đã liên kết';$('add').innerHTML='Mở Happ <span aria-hidden="true">↗</span>';for(let m of modes)$('link-'+m).value=connection.shortcuts[m];sessionStorage.setItem('mizze-connect-ui',JSON.stringify({connection,key:enteredKey}));renderExpiry();follow();}
function signal(v){if(v.timing){savedTiming=v.timing;serverClockOffset=v.receivedAt-Date.now();currentControl=v.control;renderTimers();}$('signal').textContent='Đang cập nhật';$('signal-dot').classList.add('live');for(let [key,label]of [['fakelag','FakeLag'],['ghost','Ghost'],['telekill','Telekill']]){let on=v.control[key],el=$('mode-'+key);el.textContent=label+' · '+(on?'Bật':'Tắt');el.classList.toggle('on',on);$('shortcut-'+key).textContent=on?'Đang bật':'Tắt';$('shortcut-'+key).classList.toggle('on',on);}$('signal-time').textContent='Cập nhật '+new Date(v.receivedAt).toLocaleTimeString('vi-VN');}
function follow(){clearInterval(signalTimer);let working=false;const poll=async()=>{if(working||!connection)return;working=true;try{const current=connection;const v=await api('/api/state',null,current.token);if(connection===current)signal(v);}catch{$('signal').textContent='Đang kết nối lại…';$('signal-dot').classList.remove('live');}finally{working=false}};poll();signalTimer=setInterval(poll,3000);}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,2500);}
async function copy(value,input){try{await navigator.clipboard.writeText(value);return true;}catch{if(input){input.closest('details')?.setAttribute('open','');input.focus();input.select();try{return document.execCommand('copy')}catch{}}return false;}}
$('reveal').onclick=()=>{let hidden=$('key').type==='password';$('key').type=hidden?'text':'password';$('reveal').textContent=hidden?'Ẩn':'Hiện';$('reveal').setAttribute('aria-label',hidden?'Ẩn key':'Hiện key');};
$('key-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('check').disabled=true;message('Đang kiểm tra key…');try{const key=$('key').value.trim(),v=await api('/api/login',{key,deviceId:device});enteredKey=key;license=v;grant=v.grant;connection=null;resetConnectionUi();$('key').value='';showDashboard();message(license.expiresAt?'Chọn Thêm vào Happ để kết nối.':'Thêm vào Happ sẽ bắt đầu thời hạn key.','good');}catch(e){message(e.name==='AbortError'?'Máy chủ phản hồi quá lâu. Bạn thử lại nhé.':e.message,'error');}finally{busy=false;$('check').disabled=false;}};
$('add').onclick=async()=>{if(busy)return;if(connection){location.href=connection.addUrl;return;}busy=true;$('add').disabled=true;message('Đang tạo cấu hình…');try{connection=await api('/api/provision',{grant});renderConnection();message('Mở Happ và bật VPN.','good');location.href=connection.addUrl;}catch(e){message(e.message,'error');}finally{busy=false;$('add').disabled=false;}};
$('copy').onclick=async()=>{if(await copy(connection.subscription))toast('Đã sao chép liên kết cấu hình');else message('Liên kết cấu hình: '+connection.subscription);};
for(let button of document.querySelectorAll('[data-tab]'))button.onclick=()=>selectTab(button.dataset.tab);for(let button of document.querySelectorAll('[data-go]'))button.onclick=()=>selectTab(button.dataset.go);
for(let button of document.querySelectorAll('[data-copy-mode]'))button.onclick=async()=>{const m=button.dataset.copyMode,url=connection?.shortcuts?.[m];if(!url)return;const good=await copy(url,$('link-'+m));$('shortcut-copy-status').textContent=good?'Đã sao chép. Dán vào Phím tắt.':'Liên kết đã được chọn. Nhấn giữ để sao chép.';if(good)toast('Đã sao chép liên kết');};
$('logout').onclick=()=>{clearInterval(signalTimer);clearInterval(expiryTimer);sessionStorage.removeItem('mizze-connect-ui');grant=null;connection=null;enteredKey='';license=null;resetConnectionUi();$('dashboard').hidden=true;$('login-screen').hidden=false;$('message').textContent='Nhập key để bắt đầu.';$('key').focus();};
api('/api/info').then(v=>{$('gateway').textContent=v.gateway==='ready'?'Máy chủ sẵn sàng':'Máy chủ chưa chạy';}).catch(()=>{$('gateway').textContent='Chưa nối được máy chủ';});
(async()=>{try{const saved=JSON.parse(sessionStorage.getItem('mizze-connect-ui')||'null');if(!saved?.connection?.token||!saved?.key||saved.connection.expiresAt<=Date.now()){sessionStorage.removeItem('mizze-connect-ui');return;}await api('/api/state',null,saved.connection.token);connection=saved.connection;enteredKey=saved.key;showDashboard();renderConnection();message('Đã khôi phục kết nối.','good');}catch{sessionStorage.removeItem('mizze-connect-ui');}})();

let savedTiming=null,currentControl={},serverClockOffset=0,countdownTimer=null;
function renderTimers(){if(!savedTiming)return;for(const m of modes){const input=$('seconds-'+m);if(document.activeElement!==input&&input.dataset.dirty!=='yes')input.value=String(savedTiming.seconds[m]||0);}renderCountdown();}
function renderCountdown(){clearTimeout(countdownTimer);if(!savedTiming||!connection)return;let again=false;for(const m of modes){let seconds=savedTiming.seconds[m]||0,deadline=savedTiming.offAt[m]||0,text;if(currentControl[m]&&deadline){const left=Math.max(0,(deadline-Date.now()-serverClockOffset)/1000);text=left>0?'Tự tắt sau '+left.toFixed(1)+' giây':'Đang chờ xác nhận tắt';if(left>0)again=true;}else text=currentControl[m]?'Đang bật · tắt thủ công':seconds?'Đã lưu: '+seconds+' giây':'Tắt thủ công';$('timer-state-'+m).textContent=text;}if(again)countdownTimer=setTimeout(renderCountdown,250);}
for(const form of document.querySelectorAll('[data-timer-mode]')){const m=form.dataset.timerMode,input=$('seconds-'+m);input.oninput=()=>input.dataset.dirty='yes';form.onsubmit=async event=>{event.preventDefault();if(!connection)return;const seconds=input.valueAsNumber;if(!Number.isFinite(seconds)||seconds<0||seconds>3600||Math.abs(seconds*10-Math.round(seconds*10))>0.00001){$('timer-state-'+m).textContent='Nhập số giây từ 0 đến 3600, tối đa một chữ số thập phân.';return;}const button=form.querySelector('button');button.disabled=true;$('timer-state-'+m).textContent='Đang lưu…';try{const result=await api('/api/settings',{mode:m,seconds},connection.token);input.dataset.dirty='';signal(result);toast('Đã lưu thời gian tự tắt');}catch(error){$('timer-state-'+m).textContent=error.message;}finally{button.disabled=false;}};}
